const getReceiptSubtotal = (receipt) => {
  if (!receipt) return 0;
  if (parseFloat(receipt.subtotal || 0) > 0) {
    return parseFloat(receipt.subtotal);
  }
  const items = Array.isArray(receipt.items)
    ? receipt.items
    : (typeof receipt.items === 'string' ? JSON.parse(receipt.items || '[]') : []);
  return items.reduce((sum, item) => {
    if (item.isCancelled) return sum;
    const base = item.isComplementary ? 0 : parseFloat(item.price || item.rate || 0) * parseFloat(item.qty || item.quantity || 1);
    const modifiersTotal = item.isComplementary ? 0 : (item.modifiers || []).reduce((mAcc, m) => mAcc + parseFloat(m.price || 0) * parseFloat(item.qty || item.quantity || 1), 0);
    return sum + base + modifiersTotal;
  }, 0);
};

const getReceiptGrandTotal = (receipt, isTaxInclusive = false) => {
  if (!receipt) return 0;
  const sub = getReceiptSubtotal(receipt);
  const disc = parseFloat(receipt.discountAmt || receipt.discount || 0);
  const taxC = parseFloat(receipt.tax_cgst || 0);
  const taxS = parseFloat(receipt.tax_sgst || 0);
  const sc = parseFloat(receipt.service_charge || 0);
  const dc = parseFloat(receipt.delivery_charge || receipt.delivery_charges || 0);
  const tip = parseFloat(receipt.tip_amount || receipt.tips || 0);

  const exclusiveTotal = sub - disc + taxC + taxS + sc + dc + tip;
  const inclusiveTotal = sub - disc + sc + dc + tip;

  if (!isTaxInclusive && (taxC + taxS > 0)) {
    return exclusiveTotal;
  }

  return parseFloat(receipt.total_price || 0) > 0 ? parseFloat(receipt.total_price) : inclusiveTotal;
};

